import{_ as e,o as t,c as o,a0 as r}from"./chunks/framework.CIWPqrYr.js";const u=JSON.parse('{"title":"5. Reports & Calendar","description":"","frontmatter":{},"headers":[],"relativePath":"05-reports-and-calendar.md","filePath":"05-reports-and-calendar.md"}'),s={name:"05-reports-and-calendar.md"};function n(i,a,l,d,c,p){return t(),o("div",null,[...a[0]||(a[0]=[r('<h1 id="_5-reports-calendar" tabindex="-1">5. Reports &amp; Calendar <a class="header-anchor" href="#_5-reports-calendar" aria-label="Permalink to &quot;5. Reports &amp; Calendar&quot;">​</a></h1><p>Stratos isn&#39;t just for moving cards around; it provides powerful visualizations to help you understand your data.</p><h2 id="calendar-view" tabindex="-1">Calendar View <a class="header-anchor" href="#calendar-view" aria-label="Permalink to &quot;Calendar View&quot;">​</a></h2><p>Tasks with due dates can be visualized on a Calendar.</p><ol><li>Navigate to any Board.</li><li>In the top right corner (next to Filters), click the <strong>View Toggle</strong> and select <strong>Calendar</strong>.</li><li>You will see all tasks plotted on their respective due dates.</li><li>You can drag and drop a task to a different day to quickly reschedule it.</li></ol><h2 id="reports-analytics" tabindex="-1">Reports &amp; Analytics <a class="header-anchor" href="#reports-analytics" aria-label="Permalink to &quot;Reports &amp; Analytics&quot;">​</a></h2><p>To get a bird&#39;s-eye view of your team&#39;s performance, use the Reports view.</p><ol><li>Navigate to your Board.</li><li>Click the <strong>View Toggle</strong> and select <strong>Reports</strong>.</li><li>Here you can see: <ul><li><strong>Task Distribution</strong>: A pie chart showing how many tasks are in each stage (e.g., 5 in Todo, 3 In Progress, 10 Done).</li><li><strong>Assignee Workload</strong>: See who has too much on their plate and who has capacity based on assigned Story Points.</li><li><strong>Burndown Chart</strong>: A line graph plotting remaining work over time. It calculates velocity by summing the &quot;Story Points&quot; field of all unfinished tasks. As tasks are moved to &quot;Done&quot;, the total points decrease, drawing a downward slope. If tasks don&#39;t have Story Points set, this chart will remain flat.</li></ul></li></ol>',8)])])}const g=e(s,[["render",n]]);export{u as __pageData,g as default};
